<?php require_role('buyer');$s=db()->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC');$s->execute([user()['id']]);$notes=$s->fetchAll();include __DIR__.'/../includes/header.php';?><div class="dashboard-layout"><?php include __DIR__.'/../includes/sidebar.php';?><section class="dashboard-content"><div class="dashboard-top"><div><span class="eyebrow">Centro de alertas</span><h1>Notificações</h1></div><button class="btn btn-light" data-mark-notifications>Marcar como lidas</button></div><div class="content-card notification-list"><?php foreach($notes as $n):?><div class="notification-item <?=$n['is_read']?'':'unread'?>"><span class="notification-icon"><i class="bi bi-bell"></i></span><div><strong><?=e($n['title'])?></strong><p><?=e($n['body'])?></p><small><?=date('d/m/Y H:i',strtotime($n['created_at']))?></small></div></div><?php endforeach;?></div></section></div><?php include __DIR__.'/../includes/footer.php';?>
